package app

// Grade maps a 0..100 score to a letter: <60 F, <70 D, <80 C, <90 B, else A.
func Grade(score int) string {
	switch {
	case score < 60:
		return "F"
	case score < 70:
		return "D"
	case score < 80:
		return "C"
	case score < 90:
		return "B"
	default:
		return "A"
	}
}

