package app

import "testing"

func TestGrade(t *testing.T) {
	cases := []struct {
		score int
		want  string
	}{
		{55, "F"},
		{59, "F"},
		{60, "D"},
		{75, "C"},
		{79, "C"},
		{85, "B"},
		{89, "B"},
		{90, "A"},
		{95, "A"},
		{100, "A"},
	}
	for _, c := range cases {
		if got := Grade(c.score); got != c.want {
			t.Fatalf("Grade(%d)=%q want %q", c.score, got, c.want)
		}
	}
}

