package app

import (
	"strings"
	"testing"
)

func TestGrade(t *testing.T) {
	for score := 0; score <= 100; score += 10 {
		got := Grade(score)
		if !strings.Contains("FDCBA", got) {
			t.Fatalf("Grade(%d)=%q not a letter", score, got)
		}
	}
}
